ply@anthropic.com>","tree":{"sha":"38d8c266cb04100864634bf77e13d628772e6f5a","url":"https://api.github.com/repos/agent-tracer/agent-tracer/git/trees/38d8c266cb04100864634bf77e13d628772e6f5a"},"url":"https://api.github.com/repos/agent-tracer/agent-tracer/git/commits/4887d72407bd3798a4013dd063305916bed79ef6","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/102807742?v=4","events_url":"https://api.github.com/users/belljun3395/events{/privacy}","followers_url":"https://api.github.com/users/belljun3395/followers","following_url":"https://api.github.com/users/belljun3395/following{/other_user}","gists_url":"https://api.github.com/users/belljun3395/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/belljun3395","id":102807742,"login":"belljun3395","node_id":"U_kgDOBiC4vg","organizations_url":"https://api.github.com/users/belljun3395/orgs","received_events_url":"https://api.github.com/users/belljun3395/received_events","repos_url":"https://api.github.com/users/belljun3395/repos","site_admin":false,"starred_url":"https://api.github.com/users/belljun3395/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/belljun3395/subscriptions","type":"User","url":"https://api.github.com/users/belljun3395","user_view_type":"public"},"html_url":"https://github.com/agent-tracer/agent-tracer/commit/4887d72407bd3798a4013dd063305916bed79ef6","node_id":"C_kwDOToIUx9oAKDQ4ODdkNzI0MDdiZDM3OThhNDAxM2RkMDYzMzA1OTE2YmVkNzllZjY","parents":[{"html_url":"https://github.com/agent-tracer/agent-tracer/commit/11b68f341dda5fbcabaa17f19406aeaa79636ec9","sha":"11b68f341dda5fbcabaa17f19406aeaa79636ec9","url":"https://api.github.com/repos/agent-tracer/agent-tracer/commits/11b68f341dda5fbcabaa17f19406aeaa79636ec9"}],"sha":"4887d72407bd3798a4013dd063305916bed79ef6","url":"https://api.github.com/repos/agent-tracer/agent-tracer/commits/4887d72407bd3798a4013d