INSERT INTO collection_pages VALUES('49393030c59a9f1b1d38757d421e406767c44c456545acde327a86c8a415cbca','8d4021535ea349e13598e512d96b81817e8b48c5d683bfe6bf2c0509e05aea25','{"hasNext":false,"items":[{"author":{"account":{"login":"maicondguerian","providerType":"User"},"email":"maicondguerian@gmail.com","name":"maicondguerian"},"authoredDate":"2026-07-30T14:41:57Z","committedDate":"2026-07-30T14:41:57Z","committer":{"account":{"login":"maicondguerian","providerType":"User"},"email":"maicondguerian@gmail.com","name":"maicondguerian"},"observedAt":"2026-10-08T23:59:13.812Z","repositoryId":1317371758,"sha":"9e61a9de9732f0f2c627b13ee40c8f3f531a474e"}],"observedAt":"2026-10-08T23:59:13.812Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/111819901?v=4","events_url":"https://api.github.com/users/maicondguerian/events{/privacy}","followers_url":"https://api.github.com/users/maicondguerian/followers","following_url":"https://api.github.com/users/maicondguerian/following{/other_user}","gists_url":"https://api.github.com/users/maicondguerian/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/maicondguerian","id":111819901,"login":"maicondguerian","node_id":"U_kgDOBqo8fQ","organizations_url":"https://api.github.com/users/maicondguerian/orgs","received_events_url":"https://api.github.com/users/maicondguerian/received_events","repos_url":"https://api.github.com/users/maicondguerian/repos","site_admin":false,"starred_url":"https://api.github.com/users/maicondguerian/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/maicondguerian/subscriptions","type":"User","url":"https://api.github.com/users/maicondguerian","user_view_type":"public"},"comments_url":"https://api.github.com/repos/maicondguerian/react-query-cache-leak-demo/commits/9e61a9de9732f0f2c627b13ee40c8f3f531a474e/comments","commit":{"author":{"date":"2026-07-30T14:41:57Z","email":"maicondguerian@gmail.com","name":"maicondguerian"},"comment_count":0,"committer":{"date":"2026-07-30T14:41:57Z","email":"maicondguerian@gmail.com","name":"maicondguerian"},"message":"Demo do vazamento de cache do React Query no logout\n\nReproduz em 30s o cenário em que o usuário entra com outra conta e vê os\ndados da conta anterior: logout via navigate() (SPA, sem reload) mantém o\nheap vivo, e uma query key genérica serve o cache da sessão passada.\n\nCada correção candidata é um toggle em localStorage, sem editar código:\n\n- clearOnLogout       queryClient.clear() no logout\n- scopeKeysByCompany  companyId na query key\n- stableClient        singleton de módulo vs. new QueryClient() no render\n- splitProviders      dois QueryProvider irmãos, um client cada\n\nInstrumentação: contador de requisições (prova que a conta B não chamou o\nbackend), inspetor do cache vivo e cabeçalho de contradição.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"1f19a837501665f610dccae86ada13af8f6f5f0b","url":"https://api.github.com/repos/maicondguerian/react-query-cache-leak-demo/git/trees/1f19a837501665f610dccae86ada13af8f6f5f0b"},"url":"https://api.github.com/repos/maicondguerian/react-query-cache-leak-demo/git/commits/9e61a9de9732f0f2c627b13ee40c8f3f531a474e","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/111819901?v=4","events_url":"https://api.github.com/users/maicondguerian/events{/privacy}","followers_url":"https://api.github.com/users/maicondguerian/followers","following_url":"https://api.github.com/users/maicondguerian/following{/other_user}","gists_url":"https://api.github.com/users/maicondguerian/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/maicondguerian","id":111819901,"login":"maicondguerian","node_id":"U_kgDOBqo8fQ","organizations_url":"https://api.github.com/users/maicondguerian/orgs","received_events_url":"https://api.github.com/users/maicondguerian/received_events","repos_url":"https://api.github.com/users/maicondguerian/repos","site_admin":false,"starred_url":"https://api.github.com/users/maicondguerian/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/maicondguerian/subscriptions","type":"User","url":"https://api.github.com/users/maicondguerian","user_view_type":"public"},"html_url":"https://github.com/maicondguerian/react-query-cache-leak-demo/commit/9e61a9de9732f0f2c627b13ee40c8f3f531a474e","node_id":"C_kwDOToV_btoAKDllNjFhOWRlOTczMmYwZjJjNjI3YjEzZWU0MGM4ZjNmNTMxYTQ3NGU","parents":[],"sha":"9e61a9de9732f0f2c627b13ee40c8f3f531a474e","url":"https://api.github.com/repos/maicondguerian/react-query-cache-leak-demo/commits/9e61a9de9732f0f2c627b13ee40c8f3f531a474e"}],"requestUrl":"https://api.github.com/repos/maicondguerian/react-query-cache-leak-demo/commits?per_page=100&page=1&sha=9e61a9de9732f0f2c627b13ee40c8f3f531a474e&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T15%3A43%3A31.620Z"}');
